package com.example.domain.model.i18n

internal object DuaGu3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("તારી રહમતની આશા રાખું છું", "હે અલ્લાહ! હું તારી રહમતની આશા રાખું છું, તેથી મને પલક ઝપકવા જેટલો પણ મારા મનના હવાલે ન કર, અને મારાં બધાં કામ સુધારી દે. તારા સિવા કોઈ પૂજ્ય નથી.", "પરેશાન હાલની દુઆ (દઅવાતુલ મકરૂબ).", "નબી ﷺ એ તેને પરેશાન હાલની દુઆ કહી."),
        "dua_against_enemy_ahzab" to DuaText("દુશ્મનનાં લશ્કરો સામે", "હે અલ્લાહ, કિતાબ ઉતારનાર, જલદી હિસાબ લેનાર! લશ્કરોને હરાવ. હે અલ્લાહ! તેમને હરાવ અને તેમના પગ ડગમગાવી દે.", "દુશ્મનના મુકાબલામાં — ગઝવએ અહઝાબની દુઆ.", "દુશ્મન સામે નબી ﷺ ની દુઆ."),
        "dua_anta_adudi" to DuaText("તું જ મારો સહારો છે", "હે અલ્લાહ! તું જ મારો બાહુ અને મદદગાર છે. તારા જ દ્વારા હું યોજના કરું છું, તારા જ દ્વારા હુમલો કરું છું અને તારા જ દ્વારા લડું છું.", "મુકાબલા કે મોટા પડકાર પહેલાં.", "નબી ﷺ યુદ્ધના સમયે આ ફરમાવતા."),
        "dua_ikfinihim" to DuaText("તેમના મુકાબલામાં મારા માટે પૂરતો થઈ જા", "હે અલ્લાહ! જેમ તું ચાહે તેમના મુકાબલામાં મારા માટે પૂરતો થઈ જા.", "જાલિમોની બૂરાઈથી — અસ્હાબુલ ઉખ્દૂદના છોકરાની દુઆ.", "અલ્લાહે છોકરાને જાલિમોથી બચાવી લીધો."),
        "dua_qadarullah" to DuaText("જ્યારે કંઈ ખરાબ થાય", "આ અલ્લાહની તકદીર છે, અને તેણે જે ચાહ્યું તે કર્યું.", "કોઈ અણગમતી વાત થાય ત્યારે 'કાશ' કહેવાને બદલે.", "'કાશ' શૈતાનનો દરવાજો ખોલે છે."),
        "dua_ala_kulli_hal" to DuaText("દરેક હાલમાં પ્રશંસા", "દરેક હાલમાં બધી પ્રશંસા અલ્લાહ માટે છે.", "કોઈ અણગમતી વાત થાય ત્યારે.", "નબી ﷺ અણગમતી વસ્તુ પર આ ફરમાવતા."),
        "dua_dogs_barking" to DuaText("રાત્રે કૂતરાંનું ભસવું સાંભળીને", "હું ધિક્કારાયેલા શૈતાનથી અલ્લાહની પનાહ માગું છું.", "રાત્રે કૂતરાંના ભસવા કે ગધેડાના ભૂંકવા પર.", "તેઓ એવી વસ્તુઓ જુએ છે જે તમે જોતા નથી."),
        "dua_leaving_home_adilla" to DuaText("ગુમરાહીથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું કે હું ગુમરાહ થાઉં કે ગુમરાહ કરાઉં, લપસું કે લપસાવાઉં, જુલ્મ કરું કે મારા પર જુલ્મ થાય, અજ્ઞાનતા કરું કે મારી સાથે અજ્ઞાનતા કરાય.", "ઘરેથી નીકળતી વખતે — ઉમ્મે સલમા (ર.) ની રિવાયત.", "નબી ﷺ જ્યારે પણ ઘરેથી નીકળતા ત્યારે આ પઢતા."),
        "dua_ascending_descending" to DuaText("ચઢાણ અને ઊતરાણ", "અલ્લાહ સૌથી મહાન છે (ચઢાણ પર). — અલ્લાહ પવિત્ર છે (ઊતરાણ પર).", "મુસાફરીમાં ચઢાણ પર 'અલ્લાહુ અકબર', ઊતરાણ પર 'સુબ્હાનલ્લાહ'.", "મુસાફરીમાં સહાબા (ર.) નો અમલ."),
        "dua_traveller_sahar" to DuaText("પરોઢ પહેલાં મુસાફરની દુઆ", "સાંભળનારે અલ્લાહની પ્રશંસા અને અમારા પર તેની સારી કૃપાઓ (બીજાઓ સુધી) સંભળાવી દીધી. હે અમારા રબ! અમારો સાથી બન અને અમારા પર કૃપા કર — આગથી અલ્લાહની પનાહ માગતાં (આ કહું છું).", "મુસાફરીમાં સેહરીના સમયે.", "નબી ﷺ મુસાફરીમાં સેહરીના સમયે આ ફરમાવતા."),
        "dua_zawwadakallah" to DuaText("મુસાફરને: અલ્લાહ તકવાનું ભાથું આપે", "અલ્લાહ તને તકવાનું ભાથું આપે, તારાં પાપ માફ કરે અને તું જ્યાં પણ હોય ત્યાં તારા માટે ભલાઈ આસાન કરે.", "મુસાફરને વિદાય આપતી વખતે.", "નબી ﷺ એ મુસાફરીએ જનારને આ દુઆ આપી."),
        "dua_traveller_to_resident" to DuaText("મુસાફરની પરિવાર માટે દુઆ", "હું તમને તે અલ્લાહને સોંપું છું જેની પાસે મૂકેલી અમાનતો વેડફાતી નથી.", "મુસાફરીએ જનાર પરિવારને વિદાય આપતી વખતે.", "પરિવારનું રક્ષણ અલ્લાહને સોંપવું."),
        "dua_entering_village" to DuaText("ગામ કે શહેરમાં પ્રવેશ", "હે અલ્લાહ, સાત આકાશો અને જેના પર તેમનો છાંયો છે તેના રબ, સાત ધરતીઓ અને જે તેમણે ઉપાડ્યું છે તેના રબ, શૈતાનો અને જેમને તેમણે ગુમરાહ કર્યા તેના રબ, પવનો અને જે તેમણે ઉડાડ્યું તેના રબ! અમે તારી પાસે આ વસ્તી અને તેના રહેવાસીઓની ભલાઈ માગીએ છીએ, અને તેની, તેના લોકોની અને તેમાં જે છે તેની બૂરાઈથી તારી પનાહ માગીએ છીએ.", "કોઈ વસ્તી/શહેરમાં પ્રવેશતાં પહેલાં.", "નબી ﷺ જે વસ્તીમાં પ્રવેશવા ચાહતા ત્યારે આ પઢતા."),
        "dua_vehicle_stumbles" to DuaText("સવારી લપસે ત્યારે", "અલ્લાહના નામથી.", "સવારી લપસે કે ઠોકર લાગે ત્યારે 'શૈતાન બરબાદ થાય' કહેવાને બદલે.", "બિસ્મિલ્લાહ કહેવાથી શૈતાન માખી જેવો નાનો થઈ જાય છે."),
        "dua_ajz_kasal_haram" to DuaText("લાચારી અને ઘડપણથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું લાચારી અને આળસથી, કાયરતા અને ઘડપણથી, જીવન અને મૃત્યુના ફિતનાથી, અને કબરના અઝાબથી.", "રોજિંદી પનાહની વ્યાપક દુઆ.", "નબી ﷺ ની વારંવાર માગવામાં આવતી દુઆ."),
        "dua_sharri_ma_amiltu" to DuaText("મારાં કર્મોની બૂરાઈથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું જે કર્મ મેં કર્યું તેની બૂરાઈથી, અને જે નથી કર્યું તેની બૂરાઈથી.", "આઇશા (ર.) મુજબ નબી ﷺ ની દુઆ.", "કરેલા અને ન કરેલા બંનેના અંજામથી રક્ષણ."),
        "dua_jahdil_bala" to DuaText("સખત આઝમાઇશથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું સખત આઝમાઇશથી, બદનસીબીની પકડથી, ખરાબ ફેંસલાથી અને દુશ્મનોના હસવાથી.", "સખત આઝમાઇશ અને દુશ્મનોની ખુશીથી પનાહ.", "નબી ﷺ આ ચાર વસ્તુઓથી પનાહ માગતા."),
        "dua_fitnat_ghina_faqr" to DuaText("અમીરી અને ગરીબીના ફિતનાથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું આળસ અને ઘડપણથી, પાપ અને દેવાથી, કબરના ફિતના અને અઝાબથી, આગના ફિતના અને અઝાબથી, અમીરીના ફિતનાની બૂરાઈથી, અને ગરીબીના ફિતનાથી.", "કબર, જહન્નમ, અમીરી અને ગરીબીના ફિતનાઓથી પનાહ (દુઆનો ભાગ).", "નબી ﷺ ની વ્યાપક પનાહની દુઆ."),
        "dua_kufr_faqr" to DuaText("કુફ્ર અને ગરીબીથી પનાહ", "હે અલ્લાહ! હું કુફ્ર અને ગરીબીથી તારી પનાહ માગું છું, અને કબરના અઝાબથી તારી પનાહ માગું છું. તારા સિવા કોઈ પૂજ્ય નથી.", "સવાર-સાંજ ત્રણ વખત.", "અબૂ બકરા (ર.) એ નબી ﷺ ને આ પઢતા સાંભળ્યા."),
        "dua_sharri_sami" to DuaText("મારી ઇન્દ્રિયોની બૂરાઈથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું મારા કાનની બૂરાઈથી, મારી આંખોની બૂરાઈથી, મારી જીભની બૂરાઈથી, મારા દિલની બૂરાઈથી અને મારી વાસનાની બૂરાઈથી.", "શકલ બિન હુમૈદ (ર.) ને શીખવેલી.", "અંગો અને મનને પાપથી બચાવવાની દુઆ."),
        "dua_hadm_gharaq" to DuaText("અચાનક મૃત્યુ અને અકસ્માતોથી પનાહ", "હે અલ્લાહ! હું તારી પનાહ માગું છું (મકાન) પડવાથી, ઊંચાઈ પરથી પડવાથી, ડૂબવા, બળવા અને ઘડપણથી, મૃત્યુ સમયે શૈતાનના ભટકાવવાથી, તારા માર્ગથી પીઠ ફેરવીને મરવાથી, અને (ઝેરી જાનવરના) ડંખથી મરવાથી.", "અકસ્માતો અને ખરાબ મૃત્યુથી પનાહ.", "નબી ﷺ ની પનાહની દુઆ."),
        "dua_ju_khiyanah" to DuaText("ભૂખ અને વિશ્વાસઘાતથી પનાહ", "હે અલ્લાહ! હું ભૂખથી તારી પનાહ માગું છું કારણ કે તે ખરાબ સાથી છે, અને વિશ્વાસઘાતથી તારી પનાહ માગું છું કારણ કે તે ખરાબ રાઝદાર છે.", "ભૂખ અને વિશ્વાસઘાતથી પનાહ.", "નબી ﷺ ની પનાહની દુઆ."),
        "dua_huda_tuqa" to DuaText("હિદાયત, તકવા, પાકદામની અને બેનિયાઝી", "હે અલ્લાહ! હું તારી પાસે હિદાયત, તકવા, પાકદામની અને બેનિયાઝી માગું છું.", "નબી ﷺ ની ટૂંકી વ્યાપક દુઆ.", "દીન અને દુનિયાની ચાર મૂળભૂત કૃપાઓ."),
        "dua_aslih_li_dini" to DuaText("મારો દીન, દુનિયા અને આખિરત સુધારી દે", "હે અલ્લાહ! મારો દીન સુધારી દે જે મારા દરેક કામનું રક્ષણ છે, મારી દુનિયા સુધારી દે જેમાં મારી રોજી છે, મારી આખિરત સુધારી દે જ્યાં મારે પાછા ફરવાનું છે. જીવનને મારા માટે દરેક ભલાઈમાં વધારો બનાવ, અને મૃત્યુને દરેક બૂરાઈથી રાહત બનાવ.", "દીન, દુનિયા અને આખિરત — ત્રણેયનો સુધાર.", "નબી ﷺ ની વ્યાપક દુઆ."),
        "dua_musarrifal_qulub" to DuaText("અમારાં દિલોને તારી આજ્ઞાપાલન તરફ ફેરવ", "હે અલ્લાહ, દિલો ફેરવનાર! અમારાં દિલોને તારી આજ્ઞાપાલન તરફ ફેરવી દે.", "દિલને આજ્ઞાપાલન પર જમાવવાની દુઆ.", "તમામ માણસોનાં દિલ રહમાનની બે આંગળીઓ વચ્ચે છે."),
        "dua_jannah_nar" to DuaText("જન્નત માગવી, આગથી પનાહ", "હે અલ્લાહ! હું તારી પાસે જન્નત માગું છું અને આગથી તારી પનાહ માગું છું.", "તશહ્હુદ પછી કે કોઈ પણ સમયે.", "નબી ﷺ એ ફરમાવ્યું: અમે પણ તેની આસપાસ જ દુઆ કરીએ છીએ."),
        "dua_khayri_kullih" to DuaText("બધી ભલાઈ, હમણાં અને પછી", "હે અલ્લાહ! હું તારી પાસે બધી ભલાઈ માગું છું — જલદીની અને મોડી, જે હું જાણું છું અને જે નથી જાણતો — અને બધી બૂરાઈથી તારી પનાહ માગું છું — જલદીની અને મોડી, જે હું જાણું છું અને જે નથી જાણતો. હે અલ્લાહ! હું તારી પાસે જન્નત અને તેની નજીક લઈ જનાર વાણી અને કર્મનો સવાલ કરું છું, અને આગ અને તેની નજીક લઈ જનાર વાણી અને કર્મથી પનાહ માગું છું.", "નબી ﷺ એ આઇશા (ર.) ને આ વ્યાપક દુઆ શીખવી (દુઆનો ભાગ).", "દરેક ભલાઈ સમેટતી દુઆ."),
        "dua_ihdini_saddidni" to DuaText("મને હિદાયત આપ અને સીધો રાખ", "હે અલ્લાહ! મને હિદાયત આપ અને મને સીધો રાખ.", "નબી ﷺ એ અલી (ર.) ને શીખવી.", "હિદાયતને રસ્તાની હિદાયતથી અને સીધાપણાને તીરની સીધાઈથી યાદ કરો."),
        "dua_hubbaka" to DuaText("અલ્લાહનો પ્રેમ માગવો", "હે અલ્લાહ! હું તારી પાસે તારો પ્રેમ માગું છું, અને તેનો પ્રેમ જે તને પ્રેમ કરે, અને એવો અમલ જે મને તારા પ્રેમ સુધી પહોંચાડે. હે અલ્લાહ! તારા પ્રેમને મારા માટે મારી જાત, મારા પરિવાર અને ઠંડા પાણી કરતાં પણ વધુ પ્રિય બનાવી દે.", "દાઊદ (અ.) ની દુઆ જે નબી ﷺ એ બયાન કરી.", "અલ્લાહનો પ્રેમ સૌથી મોટી દોલત."),
        "dua_filal_khayrat" to DuaText("નેકી કરવી અને બૂરાઈ છોડવી", "હે અલ્લાહ! હું તારી પાસે નેકીઓ કરવાનો, બૂરાઈઓ છોડવાનો અને ગરીબો સાથે પ્રેમનો સવાલ કરું છું, અને એ કે તું મને માફ કર અને મારા પર દયા કર. અને જ્યારે તું કોઈ કોમને ફિતનામાં નાખવા ચાહે ત્યારે મને ફિતનાથી બચાવીને મૃત્યુ આપ. હું તારી પાસે તારો પ્રેમ, તને પ્રેમ કરનારાઓનો પ્રેમ અને એવા અમલનો પ્રેમ માગું છું જે તારા પ્રેમની નજીક કરે.", "સપનામાં અલ્લાહે નબી ﷺ ને આ દુઆ શીખવી.", "નબી ﷺ એ ફરમાવ્યું: આ સત્ય છે, તેને શીખો અને શીખવો."),
        "dua_bi_ilmikal_ghayb" to DuaText("જ્યાં સુધી જીવન સારું હોય ત્યાં સુધી જીવિત રાખ", "હે અલ્લાહ! તારા ગૈબના જ્ઞાન અને સૃષ્ટિ પર તારી કુદરતના વાસ્તે — જ્યાં સુધી તારા જ્ઞાનમાં જીવન મારા માટે સારું હોય મને જીવિત રાખ, અને જ્યારે મૃત્યુ સારું હોય ત્યારે મૃત્યુ આપ. હે અલ્લાહ! હું છૂપામાં અને જાહેરમાં તારો ડર, ખુશી અને ગુસ્સામાં સાચી વાત, અને ગરીબી અને અમીરીમાં મધ્યમ માર્ગ માગું છું.", "અમ્માર બિન યાસિર (ર.) ની નમાઝની દુઆ (શરૂઆતનો ભાગ).", "નબી ﷺ નમાઝમાં આ દુઆ કરતા."),
        "dua_ism_azam_mannan" to DuaText("ઇસ્મે આઝમ: અલ-મન્નાન", "હે અલ્લાહ! હું તારી પાસે આ વાસ્તે સવાલ કરું છું કે બધી પ્રશંસા તારા માટે છે, તારા સિવા કોઈ પૂજ્ય નથી, તું ખૂબ ઉપકાર કરનાર, આકાશો અને ધરતીનો અજોડ સર્જનહાર છે. હે મહિમા અને સન્માનના માલિક, હે હંમેશા જીવંત, હે આધાર!", "નબી ﷺ એ ફરમાવ્યું આ વ્યક્તિએ ઇસ્મે આઝમ સાથે દુઆ કરી.", "આ નામથી દુઆ કરવામાં આવે તો કબૂલ થાય છે."),
        "dua_ism_azam_ahad_samad" to DuaText("ઇસ્મે આઝમ: અલ-અહદ અસ-સમદ", "હે અલ્લાહ! હું તારી પાસે આ વાસ્તે સવાલ કરું છું કે હું ગવાહી આપું છું તું જ અલ્લાહ છે, તારા સિવા કોઈ પૂજ્ય નથી, એકલો, બેનિયાઝ, જેણે કોઈને જન્મ આપ્યો નથી અને ન તે જન્મ્યો, અને તેની બરાબરીનો કોઈ નથી.", "નબી ﷺ એ ફરમાવ્યું તેણે અલ્લાહ પાસે તેના ઇસ્મે આઝમ સાથે સવાલ કર્યો.", "જ્યારે તેના દ્વારા માગવામાં આવે ત્યારે આપવામાં આવે છે, અને દુઆ કરવામાં આવે તો કબૂલ થાય છે."),
        "dua_thabbitni_hadiyan" to DuaText("મને દૃઢ, હિદાયત પામેલો અને હિદાયત આપનાર બનાવ", "હે અલ્લાહ! મને દૃઢ રાખ અને મને હિદાયત આપનાર અને હિદાયત પામેલો બનાવ.", "નબી ﷺ એ જરીર (ર.) માટે આ દુઆ કરી (પોતાના માટે 'સબ્બિતની' કહો).", "મૂળ દુઆ જરીર (ર.) માટે 'સબ્બિતહુ' શબ્દોથી છે."),
        "dua_rabbighfir_tub_alayya" to DuaText("મને માફ કર અને મારી તૌબા કબૂલ કર", "હે મારા રબ! મને માફ કર અને મારી તૌબા કબૂલ કર, નિઃશંક તું જ તૌબા કબૂલ કરનાર, દયાળુ છે.", "એક મજલિસમાં સો વખત — નબી ﷺ નો અમલ.", "સહાબાએ એક મજલિસમાં નબી ﷺ પાસેથી આ સો વખત ગણીને સાંભળ્યું."),
        "dua_rafiq_ala" to DuaText("મૃત્યુ પામતા વ્યક્તિની દુઆ", "હે અલ્લાહ! મને માફ કર, મારા પર દયા કર અને મને સર્વોચ્ચ સાથી સાથે મેળવી દે.", "નબી ﷺ ની છેલ્લી દુઆ — બીમાર પોતાના માટે.", "નબી ﷺ એ વિસાલ સમયે આ દુઆ કરી."),
        "dua_la_bas_tahur" to DuaText("બીમારને આશ્વાસન: પવિત્રતા", "કોઈ વાંધો નથી, ઇન્શાઅલ્લાહ (આ બીમારી પાપોથી) પવિત્ર કરનાર છે.", "બીમારની મુલાકાતમાં આશ્વાસન માટે.", "નબી ﷺ બીમાર પાસે જતા ત્યારે આ ફરમાવતા."),
        "dua_talqeen" to DuaText("મૃત્યુ પામતા માટે તલ્કીન", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી.", "મૃત્યુ પામતા વ્યક્તિ પાસે કલિમો પઢો (તેને જબરદસ્તી ન કરો).", "જેનો છેલ્લો શબ્દ 'લા ઇલાહા ઇલ્લલ્લાહ' હોય તે જન્નતમાં પ્રવેશશે (અબૂ દાઊદ ૩૧૧૬)."),
        "dua_ahyini_ma_kanat" to DuaText("મૃત્યુની તમન્નાને બદલે", "હે અલ્લાહ! જ્યાં સુધી જીવન મારા માટે સારું હોય મને જીવિત રાખ, અને જ્યારે મૃત્યુ મારા માટે સારું હોય ત્યારે મને મૃત્યુ આપ.", "તકલીફમાં મૃત્યુની તમન્નાને બદલે.", "નબી ﷺ એ મૃત્યુની તમન્ના કરવાની મનાઈ કરીને આ શીખવ્યું."),
        "dua_for_one_i_cursed" to DuaText("જેને વાતોથી તકલીફ આપી તેના માટે", "હે અલ્લાહ! જે મોમિનને પણ મેં ખરાબ કહ્યું હોય, તેને કયામતના દિવસે તેના માટે તારી નિકટતાનું માધ્યમ બનાવી દે.", "ગુસ્સામાં કોઈને ખરાબ કહી દીધું હોય તો તેના માટે.", "નબી ﷺ ની દુઆ."),
        "dua_praising_someone" to DuaText("કોઈની પ્રશંસા કરતી વખતે", "હું ફલાણાને આવો માનું છું, અને અલ્લાહ જ તેનો હિસાબ લેનાર છે, અને હું અલ્લાહ સામે કોઈની પવિત્રતાનો દાવો કરતો નથી.", "કોઈની પ્રશંસા કરવી હોય તો અતિશયોક્તિને બદલે.", "નબી ﷺ એ પ્રશંસાનો આ અદબ શીખવ્યો."),
        "dua_being_praised" to DuaText("જ્યારે તમારી પ્રશંસા થાય", "હે અલ્લાહ! તેઓ જે કહી રહ્યા છે તેના પર મારી પકડ ન કર, અને મારાં તે પાપ માફ કર જે તેઓ જાણતા નથી.", "પોતાની પ્રશંસા સાંભળીને — એક સહાબી (ર.) નો અમલ.", "પ્રશંસા પર અહંકારથી બચવાની રીત."),
        "dua_non_muslim_sneezes" to DuaText("જ્યારે બિનમુસ્લિમ છીંકે", "અલ્લાહ તને હિદાયત આપે અને તારી હાલત સુધારે.", "બિનમુસ્લિમ છીંકીને 'અલ્હમ્દુલિલ્લાહ' કહે ત્યારે.", "યહૂદીઓ નબી ﷺ પાસે છીંકતા કે તેઓ 'યરહમુકલ્લાહ' કહે, ત્યારે આપ આ ફરમાવતા."),
        "dua_reply_ahl_kitab_salam" to DuaText("અહલે કિતાબના સલામનો જવાબ", "અને તમારા પર પણ.", "અહલે કિતાબ સલામ કરે ત્યારે.", "નબી ﷺ નો હુકમ."),
        "dua_fasting_invited" to DuaText("રોઝામાં દાવત મળે ત્યારે", "હું રોઝાથી છું.", "રોઝાની હાલતમાં દાવત મળે કે કોઈ ઝઘડો કરે.", "રોઝેદાર દાવત કબૂલ કરે તો યજમાન માટે દુઆ કરે."),
        "dua_for_who_gave_drink" to DuaText("જેણે ખવડાવ્યું-પીવડાવ્યું તેના માટે", "હે અલ્લાહ! જેણે મને ખવડાવ્યું તેને ખવડાવ, અને જેણે મને પીવડાવ્યું તેને પીવડાવ.", "જે ખવડાવે-પીવડાવે તેના માટે.", "નબી ﷺ એ મિકદાદ (ર.) માટે આ દુઆ કરી."),
        "dua_eid_greeting" to DuaText("ઈદની મુબારકબાદી", "અલ્લાહ અમારી પાસેથી અને તમારી પાસેથી (કર્મો) કબૂલ કરે.", "ઈદના દિવસે એકબીજાને — સહાબા (ર.) નો અમલ.", "સહાબા ઈદ પર મળીને આ કહેતા."),
        "dua_wedding_night" to DuaText("નિકાહ પછી દુલ્હન માટે", "હે અલ્લાહ! હું તારી પાસે તેની ભલાઈ અને જે સ્વભાવ પર તેં તેને સર્જી તેની ભલાઈ માગું છું, અને તેની બૂરાઈ અને તે સ્વભાવની બૂરાઈથી તારી પનાહ માગું છું.", "નિકાહ પછી પત્નીના કપાળ પર હાથ મૂકીને.", "નબી ﷺ નું શિક્ષણ — નિકાહમાં બરકત."),
        "dua_istisqa_ibadak" to DuaText("તારા બંદાઓ અને જાનવરોને પાણી આપ", "હે અલ્લાહ! તારા બંદાઓ અને જાનવરોને પાણી આપ, તારી રહમત ફેલાવ અને તારી મૃત ધરતીને જીવંત કર.", "વરસાદની માગણી (ઇસ્તિસ્કા).", "નબી ﷺ વરસાદ માટે આ દુઆ કરતા."),
        "dua_seeing_clouds" to DuaText("કાળાં વાદળ જોઈને", "હે અલ્લાહ! હું તેની બૂરાઈથી તારી પનાહ માગું છું.", "આકાશમાં વાદળ જોઈને; વરસાદ પડે તો 'અલ્લાહુમ્મા સય્યિબન નાફિઆ'.", "નબી ﷺ વાદળ જોઈને કામ છોડી દેતા અને આ દુઆ કરતા."),
        "dua_jamarat" to DuaText("જમરાતની રમી", "અલ્લાહ સૌથી મહાન છે.", "દરેક કાંકરી મારતી વખતે.", "નબી ﷺ દરેક કાંકરી સાથે તકબીર કહેતા, પછી પહેલા અને બીજા જમરા પછી કિબ્લા તરફ મોઢું કરીને લાંબી દુઆ કરતા."),
        "dua_rabbi_ainni" to DuaText("હે મારા રબ, મારી મદદ કર, મારી વિરુદ્ધ નહીં", "હે મારા રબ! મારી મદદ કર અને મારી વિરુદ્ધ મદદ ન કર, મને વિજય આપ અને મારા પર વિજય ન આપ, મારા પક્ષમાં યોજના કર અને મારી વિરુદ્ધ યોજના ન કર, મને હિદાયત આપ અને હિદાયતને મારા માટે આસાન કર, અને જે મારા પર જુલ્મ કરે તેની સામે મારી મદદ કર.", "નબી ﷺ ની વ્યાપક દુઆ (શરૂઆતનો ભાગ).", "દુનિયા અને દીનની દરેક મદદ ભેગી કરતી દુઆ."),
        "dua_ati_nafsi_taqwaha" to DuaText("મારા મનને તેનો તકવા આપ", "હે અલ્લાહ! મારા મનને તેનો તકવા આપ અને તેને પવિત્ર કર, તું જ તેને સૌથી ઉત્તમ રીતે પવિત્ર કરનાર છે, તું જ તેનો કારસાઝ અને માલિક છે.", "મનના સુધાર અને શુદ્ધિ માટે.", "નબી ﷺ આ દુઆ કરતા."),
        "dua_iqsim_lana_khashyatik" to DuaText("અમને તારો એવો ડર આપ", "હે અલ્લાહ! અમને તારો એટલો ડર આપ જે અમારી અને તારી નાફરમાની વચ્ચે આડશ બને, એટલું આજ્ઞાપાલન જે અમને તારી જન્નત સુધી પહોંચાડે, અને એટલો યકીન જેનાથી દુનિયાની મુસીબતો અમારા માટે આસાન થઈ જાય. જ્યાં સુધી અમને જીવિત રાખે અમારા કાન, આંખો અને શક્તિથી અમને ફાયદો પહોંચાડ અને તેને અમારો વારસ બનાવ. જે અમારા પર જુલ્મ કરે તેની પાસેથી અમારો બદલો લે, દુશ્મનો સામે અમારી મદદ કર, અમારી મુસીબત અમારા દીનમાં ન નાખ, દુનિયાને અમારી સૌથી મોટી ચિંતા અને અમારા જ્ઞાનની સીમા ન બનાવ, અને અમારા પર એવા વ્યક્તિને ન લાદ જે અમારા પર દયા ન કરે.", "મજલિસમાંથી ઊઠતી વખતે — નબી ﷺ ભાગ્યે જ આ દુઆ કર્યા વિના ઊઠતા.", "દીન, દુનિયા અને આખિરતની ભલાઈઓની વ્યાપક દુઆ."),
        "dua_infani_bima_allamtani" to DuaText("જે શીખવ્યું તેનાથી ફાયદો આપ", "હે અલ્લાહ! તેં મને જે શીખવ્યું તેનાથી મને ફાયદો આપ, મને તે શીખવ જે મને ફાયદો આપે, અને મારા જ્ઞાનમાં વધારો કર.", "જ્ઞાન મેળવતી વખતે કે અભ્યાસ પહેલાં.", "ફાયદાકારક જ્ઞાન અને તેના પર અમલની દુઆ."),
        "dua_jar_su" to DuaText("ખરાબ પાડોશીથી પનાહ", "હે અલ્લાહ! હું કાયમી રહેઠાણના ખરાબ પાડોશીથી તારી પનાહ માગું છું, કારણ કે મુસાફરીનો પાડોશી તો બદલાઈ જાય છે.", "ખરાબ પાડોશીથી રક્ષણ માટે.", "નબી ﷺ એ તેનાથી પનાહ માગવાનો હુકમ આપ્યો."),
        "dua_ishfi_abdak" to DuaText("બીમારની શિફા માટે", "હે અલ્લાહ! તારા બંદાને શિફા આપ જેથી તે તારા માટે દુશ્મનનો મુકાબલો કરે કે તારા માટે નમાઝ તરફ ચાલીને જાય.", "બીમારની મુલાકાત વખતે તેના માટે.", "નબી ﷺ એ બીમાર માટે આ કહેવાનું શીખવ્યું."),
        "dua_la_mania" to DuaText("તું જે આપે તેને કોઈ રોકી શકતું નથી", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી, રાજ્ય અને પ્રશંસા તેની જ છે અને તે દરેક વસ્તુ પર સમર્થ છે. હે અલ્લાહ! તું જે આપે તેને કોઈ રોકનાર નથી અને તું જે રોકે તેને કોઈ આપનાર નથી, અને કોઈ અમીરને તેની અમીરી તારી સામે ફાયદો આપતી નથી.", "ફર્ઝ નમાઝના સલામ પછી.", "નબી ﷺ દરેક ફર્ઝ નમાઝ પછી આ ફરમાવતા."),
        "dua_slaughtering" to DuaText("જાનવર ઝબહ કરતી વખતે", "અલ્લાહના નામથી, અને અલ્લાહ સૌથી મહાન છે.", "કુરબાની કે ઝબહ કરતી વખતે.", "નબી ﷺ એ કુરબાની સમયે બિસ્મિલ્લાહ અને તકબીર કહી."),
        "dua_undressing" to DuaText("કપડાં ઉતારતી વખતે", "અલ્લાહના નામથી.", "કપડાં ઉતારતી વખતે (ગુસલ કે કપડાં બદલતી વખતે).", "જિન્નોની નજર અને માણસના સતર વચ્ચે પરદો બની જાય છે."),
        "dua_ilbas_jadidan" to DuaText("કોઈને નવાં કપડાંમાં જોઈને", "નવું પહેરો, પ્રશંસનીય જીવન જીવો અને શહીદ થઈને મરો.", "કોઈ મુસ્લિમ ભાઈને નવાં કપડાંમાં જોઈને.", "નબી ﷺ એ ઉમર (ર.) ને નવાં કપડાંમાં જોઈને આ દુઆ આપી."),
        "dua_hajj_la_riya" to DuaText("દેખાડાથી પાક હજ", "હે અલ્લાહ! એવો હજ જેમાં ન દેખાડો હોય ન પ્રસિદ્ધિની ઇચ્છા.", "હજની નિય્યત સમયે ઇખ્લાસ માટે.", "નબી ﷺ એ હજ સમયે આ દુઆ કરી."),
        "dua_q_muslimayni_laka" to DuaText("અમને આજ્ઞાકારી બનાવ (ઇબ્રાહીમ અને ઇસ્માઈલ અ.)", "હે અમારા રબ! અમને બંનેને તારા આજ્ઞાકારી બનાવ અને અમારી સંતાનમાંથી પણ એક ઉમ્મતને તારી આજ્ઞાકારી બનાવ, અમને અમારી ઇબાદતની રીતો બતાવ અને અમારી તૌબા કબૂલ કર, નિઃશંક તું જ તૌબા કબૂલ કરનાર, દયાળુ છે.", "પોતાના અને સંતાન માટે આજ્ઞાપાલનની દુઆ.", "કાબાના નિર્માણ વખતની દુઆ."),
        "dua_q_iftah_baynana" to DuaText("અમારી વચ્ચે ફેંસલો કર (શુઐબ અ.)", "હે અમારા રબ! અમારી અને અમારી કોમ વચ્ચે સત્ય સાથે ફેંસલો કરી દે, અને તું સૌથી ઉત્તમ ફેંસલો કરનાર છે.", "સત્ય અને અસત્ય વચ્ચે ફેંસલા માટે.", "કોમે ઇનકાર કર્યો ત્યારે શુઐબ (અ.) ની દુઆ."),
        "dua_q_la_akuna_zahiran" to DuaText("ક્યારેય ગુનેગારોનો મદદગાર નહીં (મૂસા અ.)", "હે મારા રબ! જેમ તેં મારા પર ઇનામ કર્યું, હું ક્યારેય ગુનેગારોનો મદદગાર નહીં બનું.", "અલ્લાહની કૃપાઓનો આભાર અને ગુનેગારોની મદદથી બચવાનો વાયદો.", "તૌબા પછી મૂસા (અ.) નો વાયદો."),
        "dua_q_nuh_unsurni" to DuaText("મારી મદદ કર, તેમણે મને જૂઠો ઠેરવ્યો (નૂહ અ.)", "હે મારા રબ! મારી મદદ કર કારણ કે તેમણે મને જૂઠો ઠેરવ્યો.", "જ્યારે લોકો જૂઠો ઠેરવે અને સત્યને ન માને.", "નૂહ (અ.) ની દુઆ જે કબૂલ થઈ."),
        "dua_q_ihkum_bil_haqq" to DuaText("હે મારા રબ, સત્ય સાથે ફેંસલો કર", "હે મારા રબ! સત્ય સાથે ફેંસલો કર. અને અમારો રબ રહમાન છે, જેની પાસે તમે ઘડેલી વાતો સામે મદદ માગવામાં આવે છે.", "જૂઠી વાતો અને આરોપો સામે.", "નબી ﷺ ને શીખવેલી દુઆ."),
        "dua_ghalabatid_dayn" to DuaText("ભારે દેવું અને દુશ્મનોથી પનાહ", "હે અલ્લાહ! હું દેવાના દબાણ, દુશ્મનના વર્ચસ્વ અને દુશ્મનોની ખુશીથી તારી પનાહ માગું છું.", "દેવાના બોજ અને દુશ્મનોના વર્ચસ્વથી રક્ષણ.", "નબી ﷺ આ વસ્તુઓથી પનાહ માગતા."),
        "dua_faqr_qillah_dhillah" to DuaText("ગરીબી અને અપમાનથી પનાહ", "હે અલ્લાહ! હું ગરીબી, અછત અને અપમાનથી તારી પનાહ માગું છું, અને એ વાતથી કે હું જુલ્મ કરું કે મારા પર જુલ્મ કરવામાં આવે.", "તંગી, અછત અને અપમાનથી બચવા માટે.", "નબી ﷺ એ શીખવેલી પનાહ."),
        "dua_five_things_new_muslim" to DuaText("માફી, દયા, હિદાયત, સલામતી, રોજી", "હે અલ્લાહ! મને માફ કર, મારા પર દયા કર, મને હિદાયત આપ, મને સલામતી આપ અને મને રોજી આપ.", "નબી ﷺ નવા મુસ્લિમને નમાઝ સાથે આ દુઆ શીખવતા.", "નબી ﷺ એ ફરમાવ્યું: આ શબ્દો તારા માટે દુનિયા અને આખિરત ભેગાં કરે છે."),
        "dua_ruku_laka_raka_tu" to DuaText("રુકૂમાં — તારા માટે રુકૂ કર્યું", "હે અલ્લાહ! મેં તારા માટે રુકૂ કર્યું, તારા પર ઈમાન લાવ્યો અને તારો આજ્ઞાકારી થયો. મારા કાન, આંખો, મગજ, હાડકાં અને સ્નાયુઓ તારી સામે નમી ગયાં.", "રુકૂમાં (ખાસ કરીને નફલ નમાઝમાં).", "નબી ﷺ રુકૂમાં આ પઢતા."),
        "dua_sujood_laka_sajadtu" to DuaText("સિજદામાં — તને સિજદો કર્યો", "હે અલ્લાહ! મેં તને સિજદો કર્યો, તારા પર ઈમાન લાવ્યો અને તારો આજ્ઞાકારી થયો. મારો ચહેરો તેની સામે સિજદામાં છે જેણે તેને બનાવ્યો, તેને આકાર આપ્યો અને તેના કાન અને આંખો ખોલ્યાં. બરકતવાળો છે અલ્લાહ, સૌથી ઉત્તમ સર્જનહાર.", "સિજદામાં (ખાસ કરીને નફલ નમાઝમાં).", "નબી ﷺ સિજદામાં આ પઢતા."),
        "dua_ruku_sujood_subhanaka" to DuaText("હે અમારા રબ, તું પવિત્ર છે — મને માફ કર", "હે અલ્લાહ, અમારા રબ! તું પવિત્ર છે તારી પ્રશંસા સાથે. હે અલ્લાહ! મને માફ કર.", "રુકૂ અને સિજદામાં.", "આઇશા (ર.): નબી ﷺ રુકૂ અને સિજદામાં વારંવાર આ પઢતા."),
        "dua_q_musa_li_akhi" to DuaText("મને અને મારા ભાઈને માફ કર (મૂસા અ.)", "હે મારા રબ! મને અને મારા ભાઈને માફ કર અને અમને તારી રહમતમાં દાખલ કર, અને તું સૌ દયાળુઓથી વધુ દયાળુ છે.", "પોતાના અને ભાઈ/સ્વજનો માટે માફી.", "હારૂન (અ.) માટે મૂસા (અ.) ની દુઆ."),
        "dua_q_ufawwidu_amri" to DuaText("હું મારું કામ અલ્લાહને સોંપું છું", "અને હું મારું કામ અલ્લાહને સોંપું છું, નિઃશંક અલ્લાહ બંદાઓને ખૂબ જોનાર છે.", "જ્યારે લોકો વિરોધ કરે અને મામલો અલ્લાહને સોંપવો હોય.", "ફિરઔનની કોમના મોમિનનું કથન; પછી અલ્લાહે તેને તેમની ખરાબ ચાલોથી બચાવી લીધો."),
        "dua_q_hawariyyun" to DuaText("હવારીઓની દુઆ — અમને ગવાહોમાં લખ", "હે અમારા રબ! તેં જે ઉતાર્યું તેના પર અમે ઈમાન લાવ્યા અને અમે રસૂલનું અનુસરણ કર્યું, તેથી અમને ગવાહી આપનારાઓમાં લખી લે.", "ઈમાન અને રસૂલના અનુસરણ પર દૃઢતા માટે.", "ઈસા (અ.) ના હવારીઓની દુઆ."),
        "dua_q_la_tukhzini" to DuaText("મને રુસવા ન કર (ઇબ્રાહીમ અ.)", "અને જે દિવસે લોકોને ઉઠાડવામાં આવશે તે દિવસે મને રુસવા ન કરજે.", "કયામતની રુસવાઈથી બચવા માટે.", "આખિરત માટે ઇબ્રાહીમ (અ.) ની દુઆ."),
        "dua_iftar_laka_sumtu" to DuaText("ઇફ્તાર — તારા માટે રોઝો રાખ્યો", "હે અલ્લાહ! મેં તારા માટે રોઝો રાખ્યો અને તારી જ રોજીથી ઇફ્તાર કર્યો.", "રોઝો ખોલતી વખતે (ઇફ્તારની પ્રખ્યાત દુઆ).", "નબી ﷺ ઇફ્તારના સમયે આ ફરમાવતા. આ મુરસલ રિવાયત છે જેને બીજી રિવાયતોથી ટેકો મળે છે; હનફી અને મોટા ભાગના આલિમોમાં ઇફ્તાર પર તેનું પઢવું પ્રચલિત છે."),
        "dua_iftar_ibn_umar" to DuaText("ઇફ્તાર — તારી વિશાળ રહમતથી મને માફ કર", "હે અલ્લાહ! હું તારી તે રહમતના વાસ્તે જે દરેક વસ્તુ પર છવાયેલી છે, તારી પાસે સવાલ કરું છું કે મને માફ કરી દે.", "ઇફ્તારના સમયે — અબ્દુલ્લાહ બિન અમ્ર (ર.) આ દુઆ કરતા; રોઝેદારની દુઆ ઇફ્તાર પર રદ થતી નથી.", "હદીસ: ઇફ્તારના સમયે રોઝેદારની દુઆ રદ કરવામાં આવતી નથી."),
        "dua_inni_saim" to DuaText("રોઝામાં કોઈ ઉશ્કેરે ત્યારે", "હું રોઝાથી છું, હું રોઝાથી છું.", "રોઝાની હાલતમાં કોઈ ગાળ આપે કે ઝઘડો કરે.", "નબી ﷺ એ ફરમાવ્યું: રોઝો ઢાલ છે, તેથી રોઝેદાર ન અશ્લીલ વાત કરે ન અજ્ઞાનતા — કોઈ ઝઘડે તો બે વખત આ કહે."),
        "dua_eid_takbeer" to DuaText("ઈદગાહ જતી વખતે તકબીર", "અલ્લાહ સૌથી મહાન છે, અલ્લાહ સૌથી મહાન છે, અલ્લાહ સિવા કોઈ પૂજ્ય નથી, અને અલ્લાહ સૌથી મહાન છે, અલ્લાહ સૌથી મહાન છે, અને બધી પ્રશંસા અલ્લાહ માટે જ છે.", "ચાંદરાતથી ઈદુલ ફિત્રની નમાઝ સુધી, ખાસ કરીને ઈદગાહ જતી વખતે.", "કુરઆનનો હુકમ: 'જેથી તમે ગણતરી પૂરી કરો અને અલ્લાહની મહાનતા વર્ણવો' (અલ-બકરા ૨:૧૮૫). ઇબ્ને મસઊદ (ર.) આ જ તકબીર કહેતા."),
        "dua_ahsin_aqibatana" to DuaText("દરેક કામમાં અમારો અંજામ સારો કર", "હે અલ્લાહ! તમામ કામોમાં અમારો અંજામ સારો કર, અને અમને દુનિયાની રુસવાઈ અને આખિરતના અઝાબથી બચાવી લે.", "દરેક કામના સારા અંજામ માટે.", "જે આ દુઆ કરે અને આઝમાઇશ પહેલાં મૃત્યુ પામે તે (ફિતનાથી સુરક્ષિત) મર્યો."),
        "dua_fadlika_wa_rahmatik" to DuaText("તારી કૃપા અને રહમતનો સવાલ", "હે અલ્લાહ! હું તારી પાસે તારી કૃપા અને તારી રહમત માગું છું, કારણ કે તેમનો માલિક તારા સિવા કોઈ નથી.", "રોજી અને રહમત માગતી વખતે.", "નબી ﷺ પાસે મહેમાન આવ્યા અને ખાવાનું ન હતું ત્યારે આપે આ દુઆ કરી, પછી ભેટ આવી."),
        "dua_allahu_akbar_kabira_2696" to DuaText("એક ગામડિયાને શીખવેલા શબ્દો", "અલ્લાહ સિવા કોઈ પૂજ્ય નથી, તે એકલો છે, તેનો કોઈ ભાગીદાર નથી. અલ્લાહ ખૂબ જ મહાન છે, અલ્લાહની ઘણી પ્રશંસા છે, સર્વ જગતનો રબ અલ્લાહ પવિત્ર છે, અને જબરદસ્ત, હિકમતવાળા અલ્લાહ સિવા કોઈ શક્તિ અને સામર્થ્ય નથી.", "ઝિક્ર અને દુઆનું વ્યાપક વાક્ય — એક ગામડિયાને શીખવ્યું.", "પછી 'અલ્લાહુમ્મગફિર લી વરહમ્ની વહદિની વરઝુક્ની' કહેવાનું શીખવ્યું."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("આગલાં-પાછલાં પાપ માફ કર", "હે અલ્લાહ! મારાં તે પાપ માફ કર જે મેં પહેલાં કર્યાં અને પછી કર્યાં, છૂપાં કર્યાં અને જાહેરમાં કર્યાં, જે અતિશયોક્તિ કરી, અને જે તું મારા કરતાં વધુ જાણે છે. તું જ આગળ કરનાર અને તું જ પાછળ કરનાર છે, તારા સિવા કોઈ પૂજ્ય નથી.", "તશહ્હુદ અને દુરૂદ પછી સલામ પહેલાં.", "નબી ﷺ નમાઝના અંતે તશહ્હુદ અને સલામ વચ્ચે આ પઢતા."),
        "dua_jiddi_wa_hazli" to DuaText("ગંભીરતા અને મજાકનાં પાપ માફ કર", "હે અલ્લાહ! મારાં તે પાપ માફ કર જે ગંભીરતામાં થયાં અને મજાકમાં, ભૂલથી થયાં અને જાણીજોઈને — અને આ બધું મારામાં છે.", "જાણે-અજાણે દરેક પ્રકારનાં પાપોની માફી.", "નબી ﷺ નું વ્યાપક ઇસ્તિગફાર."),
        "dua_rising_ruku_mil" to DuaText("રુકૂ પછી — આકાશ ભરીને પ્રશંસા", "હે અમારા રબ! તારા માટે જ બધી પ્રશંસા છે, આકાશો ભરીને, ધરતી ભરીને, અને તે પછી જે વસ્તુ તું ચાહે તે ભરીને.", "રુકૂમાંથી ઊઠીને 'રબ્બના લકલ હમ્દ' સાથે.", "નબી ﷺ રુકૂમાંથી ઊઠીને આ ફરમાવતા."),
        "dua_istiftah_kabira" to DuaText("અલ્લાહ મહાન, ઘણી પ્રશંસા", "અલ્લાહ ખૂબ જ મહાન છે, અલ્લાહની ઘણી પ્રશંસા છે, અને સવાર-સાંજ અલ્લાહની પવિત્રતા છે.", "નમાઝ શરૂ કરતી વખતે (સનાનું એક સ્વરૂપ).", "નબી ﷺ એ ફરમાવ્યું: તેના માટે આકાશના દરવાજા ખોલી દેવાયા."),
        "dua_q_ashku_bathhi" to DuaText("હું ફક્ત અલ્લાહ પાસે ફરિયાદ કરું છું (યાકૂબ અ.)", "હું મારી પરેશાની અને દુઃખની ફરિયાદ ફક્ત અલ્લાહ પાસે કરું છું.", "ઊંડા દુઃખ અને જુદાઈના સમયે.", "યાકૂબ (અ.) એ યૂસુફ (અ.) ની જુદાઈમાં આ કહ્યું."),
        "dua_q_khayrun_hafiza" to DuaText("અલ્લાહ ઉત્તમ રક્ષક છે", "અલ્લાહ જ ઉત્તમ રક્ષક છે, અને તે સૌ દયાળુઓથી વધુ દયાળુ છે.", "બાળકો કે સ્વજનોને મુસાફરીએ મોકલતી વખતે.", "યાકૂબ (અ.) એ પોતાના દીકરાને અલ્લાહને સોંપતાં આ કહ્યું."),
        "dua_q_aqraba_rashada" to DuaText("મારો રબ મને ભલાઈની નજીકનો માર્ગ બતાવશે", "આશા છે કે મારો રબ મને આનાથી પણ વધુ ભલાઈની નજીકનો માર્ગ બતાવશે.", "કોઈ કામમાં વધુ સારો માર્ગ શોધતી વખતે.", "ભૂલી જવા પર નબી ﷺ ને આ કહેવાનું શીખવાયું."),
        "dua_q_sawa_as_sabil" to DuaText("મને સીધો માર્ગ બતાવ (મૂસા અ.)", "આશા છે કે મારો રબ મને સીધો માર્ગ બતાવશે.", "નવી મુસાફરી કે અજાણ્યા માર્ગે ચાલતી વખતે.", "મદયન તરફ જતાં મૂસા (અ.) એ આ કહ્યું."),
        "dua_q_not_among_wrongdoers" to DuaText("મને જાલિમોમાં શામેલ ન કર", "હે મારા રબ! મને જાલિમ લોકોમાં શામેલ ન કર.", "જાલિમોથી અલગ રાખવા માટે અલ્લાહ પાસે દુઆ."),
        "dua_q_do_not_make_us_trial" to DuaText("અમને આઝમાઇશ ન બનાવ", "હે અમારા રબ! અમને કાફિરો માટે આઝમાઇશ ન બનાવ અને અમને માફ કર, હે અમારા રબ! નિઃશંક તું જ જબરદસ્ત, હિકમતવાળો છે.", "ઇબ્રાહીમ (અ.) અને તેમના સાથીઓની દુઆ."),
        "dua_morning_witness" to DuaText("સવારે તૌહીદની ગવાહી", "હે અલ્લાહ! મેં સવાર કરી, હું તને, તારા અર્શ ઉપાડનારાઓને, તારા ફરિશ્તાઓને અને તારી સમગ્ર સૃષ્ટિને ગવાહ બનાવું છું કે તું જ અલ્લાહ છે, તારા સિવા કોઈ પૂજ્ય નથી, તું એકલો છે, તારો કોઈ ભાગીદાર નથી, અને મુહમ્મદ ﷺ તારા બંદા અને રસૂલ છે.", "રિવાયતમાં સવારે ચાર વખત પઢવાનો ઉલ્લેખ છે."),
        "dua_evening_witness" to DuaText("સાંજે તૌહીદની ગવાહી", "હે અલ્લાહ! મેં સાંજ કરી, હું તને, તારા અર્શ ઉપાડનારાઓને, તારા ફરિશ્તાઓને અને તારી સમગ્ર સૃષ્ટિને ગવાહ બનાવું છું કે તું જ અલ્લાહ છે, તારા સિવા કોઈ પૂજ્ય નથી, તું એકલો છે, તારો કોઈ ભાગીદાર નથી, અને મુહમ્મદ ﷺ તારા બંદા અને રસૂલ છે.", "રિવાયતમાં સાંજે ચાર વખત પઢવાનો ઉલ્લેખ છે."),
        "dua_morning_blessing" to DuaText("સવારે કૃપાઓનો આભાર", "હે અલ્લાહ! સવારે મને કે તારી કોઈ પણ સૃષ્ટિને જે કૃપા મળી તે ફક્ત તારી તરફથી છે, તારો કોઈ ભાગીદાર નથી; તેથી બધી પ્રશંસા અને આભાર તારો જ છે.", "સવારે અલ્લાહની કૃપાઓ પર આભારનો ઝિક્ર."),
        "dua_evening_blessing" to DuaText("સાંજે કૃપાઓનો આભાર", "હે અલ્લાહ! સાંજે મને કે તારી કોઈ પણ સૃષ્ટિને જે કૃપા મળી તે ફક્ત તારી તરફથી છે, તારો કોઈ ભાગીદાર નથી; તેથી બધી પ્રશંસા અને આભાર તારો જ છે.", "સાંજે અલ્લાહની કૃપાઓ પર આભારનો ઝિક્ર."),
    )
}
